const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const systems={Brain:['Brain & nervous system','Neurological','glioblastoma OR Alzheimer disease OR Parkinson disease'],Skin:['Skin & melanoma','Skin & melanoma','melanoma'],Heart:['Heart & circulation','Cardiovascular','heart disease'],Lungs:['Lungs & respiration','Respiratory','lung disease'],Digestive:['Digestive system','Digestive','digestive disease'],Kidneys:['Kidneys & urinary system','Renal','kidney disease'],Blood:['Blood & immune system','Hematological','leukemia OR lymphoma'],Bones:['Bones & joints','Musculoskeletal','arthritis']};let area='Brain',studies=[],saved=JSON.parse(localStorage.getItem('dh-saved')||'[]'),savedMode=false,request=0,currentCompound='temozolomide',cid=null,viewer=null,retro=true;
function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');setTimeout(()=>$('toast').classList.add('hidden'),3500)}
function counts(){$('savedcount').textContent=saved.length;$('statSaved').innerHTML=saved.length+' <em>saved trials</em>'}counts();
$('areas').innerHTML=Object.keys(systems).map(a=>`<button class="chip ${a===area?'active':''}" aria-pressed="${a===area?'true':'false'}" data-area="${a}">${a}</button>`).join('');
document.querySelectorAll('[data-area]').forEach(el=>{el.onclick=()=>{area=el.dataset.area;savedMode=false;$('search').value='';document.querySelectorAll('[data-area]').forEach(e=>e.classList.toggle(e.classList.contains('organ')?'selected':'active',e.dataset.area===area));$('areaLabel').textContent=systems[area][0];$('contextArea').textContent=systems[area][0];document.querySelectorAll('[data-area]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.area===area)));$('trialHeading').textContent=systems[area][1]+' clinical trials';loadTrials()};if(el.tagName.toLowerCase()!=='button')el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.onclick()}}});
async function loadTrials(){renderNews();let token=++request;$('trials').innerHTML='<div class="empty">Searching the clinical trial registry…</div>';$('resultCount').textContent='Loading';$('dataStatus').textContent='ClinicalTrials.gov · requesting current registry records';const params=new URLSearchParams({'query.cond':$('search').value.trim()||systems[area][2],pageSize:'30',format:'json',countTotal:'true'});if($('status').value)params.set('filter.overallStatus',$('status').value);try{const r=await fetch('https://clinicaltrials.gov/api/v2/studies?'+params,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error(r.status);const data=await r.json();if(token!==request)return;studies=data.studies||[];$('dataStatus').textContent='Registry fetched '+new Date().toLocaleString()+' · individual records may lag site status';renderTrials()}catch(e){if(token!==request)return;studies=[];$('resultCount').textContent='Unavailable';$('dataStatus').textContent='Registry connection unavailable · no live status asserted';$('trials').innerHTML=`<div class="empty">We couldn't reach ClinicalTrials.gov. Try refreshing, or browse the registry directly.<br><a href="https://clinicaltrials.gov/search?cond=${encodeURIComponent($('search').value||systems[area][2])}" target="_blank" rel="noopener">Open matching registry search ↗</a><br><button class="outline" onclick="loadTrials()">Try again</button></div>`}}
function filtered(){return(savedMode?saved:studies).filter(s=>{let p=s.protocolSection;return(!$('phase').value||(p.designModule?.phases||[]).includes($('phase').value))&&(!$('modality').value||(p.armsInterventionsModule?.interventions||[]).some(x=>x.type===$('modality').value))})}
function renderTrials(){let list=filtered();$('resultCount').textContent=list.length+' records';$('trials').innerHTML=list.length?list.slice(0,3).map(s=>{let p=s.protocolSection,id=p.identificationModule.nctId,status=p.statusModule.overallStatus.replaceAll('_',' '),phase=(p.designModule?.phases||['Not specified']).join(' / ').replaceAll('PHASE','Phase ');return`<article class="trial"><div class="trialtop"><div><span class="tag ${p.statusModule.overallStatus==='RECRUITING'?'pass':['TERMINATED','WITHDRAWN','SUSPENDED'].includes(p.statusModule.overallStatus)?'warn':''}">${esc(status)}</span> <span class="tag phase">${esc(phase)}</span></div><button class="save" aria-pressed="${saved.some(x=>x.protocolSection.identificationModule.nctId===id)}" aria-label="Toggle saved trial ${id}" onclick="saveTrial('${id}')">${saved.some(x=>x.protocolSection.identificationModule.nctId===id)?'Saved':'Save'}</button></div><h3>${esc(p.identificationModule.briefTitle)}</h3><p>${esc((p.conditionsModule?.conditions||[]).slice(0,2).join(' · '))}</p><div class="trialfoot"><span>${esc(id)} · Updated ${esc(p.statusModule.lastUpdatePostDateStruct?.date||'unknown')}</span><button onclick="details('${id}')">View trial ↗</button></div></article>`}).join(''):'<div class="empty">No matching records in this result set. Try another filter or condition.</div>';if(list.length>3)$('trials').innerHTML+=`<div class="countnote">Showing 3 of ${list.length} fetched matches. <button class="outline" onclick="showAll()">View all</button></div>`}
function showAll(){showDialog('<h2>All matching trials</h2>'+filtered().map(s=>`<p><button class="trial-list-link" onclick="details('${esc(s.protocolSection.identificationModule.nctId)}')">${esc(s.protocolSection.identificationModule.briefTitle)} · View details</button></p>`).join(''))}
function saveTrial(id){let i=saved.findIndex(s=>s.protocolSection.identificationModule.nctId===id);if(i>=0)saved.splice(i,1);else{let s=studies.find(s=>s.protocolSection.identificationModule.nctId===id);if(s)saved.push(s)}localStorage.setItem('dh-saved',JSON.stringify(saved));counts();renderTrials()}
function showDialog(html){$('dialog').classList.remove('trial-detail');$('dialogbody').innerHTML=html;if(!$('dialog').open)$('dialog').showModal()}
$('close').onclick=()=>$('dialog').close();$('searchform').onsubmit=e=>{e.preventDefault();savedMode=false;loadTrials()};$('refresh').onclick=()=>{savedMode=false;loadTrials()};$('status').onchange=loadTrials;['phase','modality'].forEach(id=>$(id).onchange=renderTrials);
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-nav]').forEach(x=>{x.classList.toggle('active',x===b);if(x===b)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});let n=b.dataset.nav;if(n==='news')$('researchNews').scrollIntoView({behavior:'smooth'});if(n==='designer')$('workspace').scrollIntoView({behavior:'smooth'});if(n==='explore'){savedMode=false;$('trialHeading').textContent=systems[area][1]+' clinical trials';renderTrials();$('explorer').scrollIntoView({behavior:'smooth'})}if(n==='saved'){savedMode=true;$('trialHeading').textContent='Your saved research';$('dataStatus').textContent='Saved locally in this browser · refresh registry to check current status';renderTrials();$('explorer').scrollIntoView({behavior:'smooth'})}if(n==='about')showDialog('<h2>Science with provenance</h2><p>Discovery includes a curated collection of news reporting, research-institution reports, and sponsor announcements, each labeled by source type and publication date. Reports are not automatically refreshed and may describe historical results. Source checking confirms attribution, not independent replication. Verified trial links connect reports to registry records; recruitment status comes from the registry only. News follows body-system selection and has its own search and source filters.</p><p>Registry trials are fetched on demand from the ClinicalTrials.gov API. Registry data are submitted by study sponsors and may not reflect changes at individual sites. A recruiting label does not establish personal eligibility.</p><p>Structures and calculated descriptors come from PubChem. XLogP is a calculated partition coefficient, not an experimental measurement. Drug names may resolve to salts or parent compounds; verify identity before interpretation.</p><p>Biologics and cell therapies may not have meaningful small molecule descriptors. No affinity, pKa, efficacy, or confidence intervals are invented when validated evidence is unavailable.</p><p>Saved research stays in your browser. This workspace supports research, not treatment decisions.</p>')});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1});['structure','routes','evidence'].forEach(id=>$(id).classList.toggle('hidden',id!==b.dataset.tab))});
let viewRequest=0;let molRequest=0;async function loadMol(){const token=++molRequest;++viewRequest;let q=$('compound').value.trim();if(!q)return;$('molnote').textContent='Resolving compound and calculated properties…';let type=/[=\[\]#@()]/.test(q)?'smiles':'name';try{let r=await fetch(`https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/${type}/${encodeURIComponent(q)}/property/MolecularWeight,TPSA,HBondDonorCount,XLogP,CanonicalSMILES/JSON`,{signal:AbortSignal.timeout(16000)});if(!r.ok)throw Error();let p=(await r.json()).PropertyTable.Properties[0];if(token!==molRequest)return;cid=p.CID;currentCompound=q;viewer=null;$('molname').textContent=q;$('molsub').textContent='PubChem CID '+cid+' · verify compound identity';$('viewer').innerHTML='<div class="empty">Loading 3D conformer…</div>';$('viewlabel').textContent='Loading 3D structure…';let smi=p.ConnectivitySMILES||p.CanonicalSMILES||p.SMILES||'';let arom=(smi.match(/[bcnops]/g)||[]).length;let vals=[['Molecular weight (g/mol)',p.MolecularWeight,'CALC'],['TPSA (Å²)',p.TPSA,'CALC'],['H-bond donors (count)',p.HBondDonorCount,'CALC'],['cLogP / XLogP',p.XLogP??'N/A','CALC'],['Aromatic atoms (count)',arom||'Not assigned','SMILES'],['pKa heuristic','Unavailable','NO MODEL']];$('properties').innerHTML=vals.map(v=>`<div class="property"><small>${v[0]}</small><strong>${esc(v[1])}<span class="provenance">${v[2]}</span></strong></div>`).join('');$('molnote').textContent='PubChem calculated descriptors · aromatic atoms counted from aromatic SMILES tokens. No validated pKa model connected.';$('smilesout').textContent='SMILES: '+(smi||'not provided');$('targetname').textContent=q;$('targettext').textContent=q.toLowerCase()==='temozolomide'?'DNA methylation is the relevant mechanism; a single receptor binding affinity is not an appropriate summary.':'Target mechanism and assay evidence have not been loaded for this compound.';await render3D()}catch(e){if(token!==molRequest)return;$('molnote').textContent='Compound lookup unavailable. Check the name / SMILES and retry. Large therapies may not resolve in PubChem.';toast('Could not resolve this compound. Previous structure retained.')}}
$('loadmol').onclick=loadMol;$('compound').onkeydown=e=>{if(e.key==='Enter')loadMol()};$('resetmol').onclick=()=>{if(viewer){viewer.zoomTo();viewer.render()}else loadMol()};async function molecularLibrary(){if(window.$3Dmol)return window.$3Dmol;return new Promise((resolve,reject)=>{const script=document.querySelector('script[src*="3Dmol"]');if(!script)return reject(Error('library'));const timeout=setTimeout(()=>reject(Error('library')),12000);script.addEventListener('load',()=>{clearTimeout(timeout);window.$3Dmol?resolve(window.$3Dmol):reject(Error('library'))},{once:true});script.addEventListener('error',()=>{clearTimeout(timeout);reject(Error('library'))},{once:true})})}
async function render3D(){if(!cid)return;const selectedCid=cid,token=++viewRequest;$('viewlabel').textContent='Loading 3D conformer…';$('view3d').textContent='Loading…';$('view3d').disabled=true;try{const [lib,r]=await Promise.all([molecularLibrary(),fetch(`https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/cid/${selectedCid}/SDF?record_type=3d`,{signal:AbortSignal.timeout(16000)})]);if(!r.ok)throw Error('conformer');const sdf=await r.text();if(token!==viewRequest)return;if(viewer)viewer.clear();$('viewer').innerHTML='';viewer=lib.createViewer($('viewer'),{backgroundColor:getComputedStyle(document.documentElement).getPropertyValue('--sunk').trim()});const model=viewer.addModel(sdf,'sdf');if(!model.selectedAtoms({}).length)throw Error('empty structure');viewer.setStyle({},{stick:{radius:.16},sphere:{scale:.26}});viewer.zoomTo();viewer.resize();viewer.render();$('viewlabel').textContent='3D conformer · drag to rotate · scroll to zoom';$('view3d').textContent='Recenter 3D'}catch(e){if(token!==viewRequest)return;viewer=null;$('viewer').innerHTML=`<img id="molimg" alt="2D fallback structure; 3D unavailable" src="https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/cid/${selectedCid}/PNG">`;$('viewlabel').textContent='3D unavailable · showing 2D fallback';$('view3d').textContent='Retry 3D'}finally{if(token===viewRequest)$('view3d').disabled=false}}
$('view3d').onclick=()=>{if(viewer){viewer.zoomTo();viewer.render()}else render3D()};
if(window.ResizeObserver)new ResizeObserver(()=>{if(viewer){viewer.resize();viewer.render()}}).observe($('viewer'));

function route(){let aspirin=$('reaction').value==='aspirin',a=aspirin?'Salicylic acid + acetic anhydride':'1,3-butadiene + ethene',b=aspirin?'Aspirin + acetic acid':'Cyclohexene';$('routebox').textContent=retro?b+' ⟵ '+a:a+' ⟶ '+b}route();$('reaction').onchange=route;$('direction').onclick=()=>{retro=!retro;$('direction').textContent='Direction: '+(retro?'retrosynthesis':'forward synthesis')+' ⇄';route()};loadTrials();loadMol();
